	                        // Set the text of the button.
	                        text: jQuery(this).data("update")
	                    }
	                });

	                custom_file_frame.on( "select", function() {
	           
	                    // Grab the selected attachment.
	                    var attachment = custom_file_frame.state().get("selection").first();
	
